/** autogenerated **/
Ext._define('common.functionalId.PendentSignManage', {
    extend: 'toolkit.widget.TabPanel',

    getFunctionalIdGrid: function() {
        if(!this._functionalIdGrid) {
            this._functionalIdGrid = Ext._create('common.functionalId.Grid', {
                region: 'center',
                gridAutoLoad: true,
                configOrderToolBar: ['edit', 'remove', '-', 'print', 'markAs', '-', 'search', '->', 'download'],
                onlyColumns: [
                    'name',
                    'version',
                    'signed_by_unicode',
                    'signed_at',
                    'revoked_by_unicode',
                    'revoked_at',
                ]
            });

            this._functionalIdGrid.getSelectionModel().on({
                scope: this,
                selectionchange: function(sel) {
                    var selection = sel.getSelections();

                    if (selection.length > 0) {
                        this.functionalId(selection[0]);
                    } else {
                        this.functionalId(null);
                    }
                }
            });
        }

        return this._functionalIdGrid;
    },

    functionalId: function(value, dispatch) {
        dispatch = (dispatch === undefined ? true : dispatch);

        if(value !== undefined) {
            this._functionalId = value;

            if(dispatch)
                this.functionalIdObserve();
        }

        return this._functionalId;
    },

    functionalIdObserve: function() {
        var record = this.functionalId();
        var panel = this.getSamplePanel();

        if (record && (record.get('version') || record.get('pk'))) {
            var mask = new Ext.LoadMask(this.getSamplePanel().getEl(), {msg: 'buscando informações ...'});

            panel.enable();
            mask.show();
            this.getFunctionalIdGrid().factoryRestful().preview(
                record.data,
                {
                    scope: this,
                    fn: function(rst) {
                        this.getSamplePanel().setPageContent(rst.content);
                    }
                },
                {
                    scope: this,
                    fn: function(message) {
                        this.getSamplePanel().setPageContent([
                            '<p style="padding: 5px">Ocorreu um erro buscando informações da Carteira Funcional</p>',
                            '<p style="padding: 5px">Mensagem: "' + message + '"</p>'
                        ].join(''));
                    }
                },
                { fn: function() { mask.hide(); }}
            );
        }
        else {
            panel.disable();
            this.getSamplePanel().setPageContent('');
        }
    },

    getSamplePanel: function(cfg) {
        if(!this._samplePanel)
            this._samplePanel = Ext._create('core.TilePagePanel', {
                region: 'east',
                split: true,
                width: 850,
                minWidth: 850
            });

        return this._samplePanel;
    },

    constructor: function(cfg) {
        cfg = core.nullValue(cfg, {});

        Ext.applyIf(
            cfg,
            {
                title: 'Pendências de Emissão'
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getFunctionalIdGrid(cfg),
                    this.getSamplePanel(cfg)
                ]
            }
        );

        common.functionalId.PendentSignManage.superclass.constructor.call(this, cfg);
    }
});
